import datetime
import json
import subprocess

UTC = datetime.timezone.utc

def run(args, timeout=60):
    p = subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True, timeout=timeout)
    return {'command': args, 'returncode': p.returncode, 'stdout': p.stdout, 'stderr': p.stderr}

started = datetime.datetime.now(UTC)
out = {'started_at_utc': started.isoformat(), 'hostname': run(['hostname']), 'queries': {}}
inspection = run(['docker', 'inspect', 'video-analytics-midterm-postgres'])
if inspection['returncode']:
    raise RuntimeError('postgres inspect failed: ' + inspection['stderr'])
env = dict(v.split('=', 1) for v in json.loads(inspection['stdout'])[0]['Config']['Env'] if '=' in v)
user = env.get('POSTGRES_USER', 'postgres')
dbname = env.get('POSTGRES_DB', user)
queries = {
  'schema': "SELECT table_name,column_name,data_type FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('cameras','evidence_tasks','camera_rules') ORDER BY table_name,ordinal_position",
  'art_report_metadata': None,
}
for name, query in queries.items():
    if query is None:
        continue
    sql = "BEGIN READ ONLY; SET LOCAL statement_timeout='30s'; SELECT row_to_json(q) FROM (" + query + ") q; ROLLBACK;"
    result = run(['docker','exec','video-analytics-midterm-postgres','psql','-X','-qAt','-v','ON_ERROR_STOP=1','-U',user,'-d',dbname,'-c',sql])
    result['command'] = ['docker','exec','video-analytics-midterm-postgres','psql','-X','-qAt','-v','ON_ERROR_STOP=1','-U','<from container POSTGRES_USER>','-d','<from container POSTGRES_DB>','-c',sql]
    out['queries'][name] = result
art = '/data/video-analytics/artifacts/pressure60_allalg_rr157_uos157_1h_20261013_qwen27b_face4_remux2'
for filename in ['run_config.json', 'report.json']:
    try:
        with open(art + '/' + filename) as f:
            data=json.load(f)
        if filename == 'run_config.json':
            selected={k:v for k,v in data.items() if any(t in k for t in ['source','run_id','discard','cleanup','pressure_camera','cameras'])}
        else:
            selected={k:v for k,v in data.items() if any(t in k for t in ['cleanup','db_summary_before_cleanup','pressure_cameras','restored'])}
        out[filename] = selected
    except Exception as exc:
        out[filename] = {'error': str(exc)}
out['completed_at_utc'] = datetime.datetime.now(UTC).isoformat()
print(json.dumps(out, ensure_ascii=True, indent=2))
